        Steps           []stepReport `json:"steps"`
}

type trendStep struct {
        StepID         string    `json:"step_id"`
        Statuses       []*string `json:"statuses"`
        FirstSeenIndex int       `json:"first_seen_index"`
        LastSeenIndex  int       `json:"last_seen_index"`
        StatusChanges  int       `json:"status_changes"`
        Stability      float64   `json:"stability"`
        Classification string    `json:"classification"`
}

type trendAggregate struct {
        TotalStepsTracked int     `json:"total_steps_tracked"`
        StableCount       int     `json:"stable_count"`
        FlakyCount        int     `json:"flaky_count"`
        DegradingCount    int     `json:"degrading_count"`
        ImprovingCount    int     `json:"improving_count"`
        OverallStability  float64 `json:"overall_stability"`
}

type trendOutput struct {
        TrendTimestamp string         `json:"trend_timestamp"`
        ReportCount    int            `json:"report_count"`
        StepTrends     []trendStep    `json:"step_trends"`
        Aggregate      trendAggregate `json:"aggregate"`
}

func trendCmd(args []string) {
        format := "json"
        positional := parseFlags(args, map[string]*string{
                "format": &format,
        })

        if len(positional) < 2 {
                fmt.Fprintln(os.Stderr, "error: trend requires at least two report files")
                os.Exit(2)
        }

        reports := make([]*trendReportLite, 0, len(positional))
        for _, path := range positional {
                rep, err := loadTrendReport(path)
                if err != nil {
                        fmt.Fprintln(os.Stderr, err)
                        os.Exit(2)
                }
                reports = append(reports, rep)
        }

        output := buildTrendOutput(reports)

        if format == "text" {
                printTrendText(output)
        } else {
                data, err := json.MarshalIndent(output, "", "  ")
                if err != nil {
                        fmt.Fprintf(os.Stderr, "error: %s\n", err)
                        os.Exit(2)
                }
                fmt.Println(string(data))
        }

        if output.Aggregate.DegradingCount > 0 || output.Aggregate.FlakyCount > 0 {
                os.Exit(1)
        }
        os.Exit(0)
}

